SELECT
  CASE WHEN x THEN 1 ELSE CASE WHEN c THEN 4 ELSE 5 END END AS in_else
  , CASE WHEN x THEN CASE WHEN c THEN 4 ELSE 5 END ELSE 0 END AS in_then
  , CASE WHEN x THEN CASE WHEN c THEN CASE WHEN d THEN 6 END END END AS three_deep
  , CASE
      WHEN a = 1 THEN CASE WHEN b THEN 'b' ELSE 'not b' END
      WHEN a = 2 THEN 'two'
      ELSE CASE WHEN c THEN 'c' END
    END AS in_multi_when
FROM t
